<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../api';import{useSessionStore}from'../../stores/session';import type{Task}from'../../types';const session=useSessionStore(),items=ref<Task[]>([]),active=ref('all'),tabs=[['all','全部'],['waiting','待处理'],['available','待接单'],['delivering','进行中'],['completed','已完成']];async function load(s=active.value){active.value=s;items.value=await api.tasks(session.role,s)}onShow(()=>load());</script>
<template><view class="page"><scroll-view scroll-x class="tabs"><view class="tabs__inner"><view v-for="t in tabs" :key="t[0]" class="tab" :class="{'tab--active':active===t[0]}" @tap="load(t[0])">{{t[1]}}</view></view></scroll-view><view v-if="!items.length" class="empty card">当前分类没有任务</view><view v-for="task in items" :key="task.id" class="task card" @tap="uni.navigateTo({url:`/pages/task/detail?id=${task.id}`})"><view class="head"><text>{{task.packageNo}}</text><text class="status">{{task.statusText}}</text></view><text class="address">{{task.building}} · {{task.floor}} 楼 · {{task.room}}</text><view class="meta"><text>{{task.itemCount}} 件</text><text>{{task.weight}} kg</text><text>{{task.modeText}}</text><text>¥{{task.commission}}</text></view></view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.tabs{white-space:nowrap;margin-bottom:24rpx}.tabs__inner{display:flex;gap:12rpx}.tab{padding:16rpx 28rpx;border-radius:32rpx;background:#fff;border:2rpx solid $line}.tab--active{background:$primary;color:#fff}.task{padding:28rpx;margin-bottom:20rpx}.head,.meta{display:flex;justify-content:space-between;gap:14rpx}.head{font-weight:800}.address{display:block;font-size:36rpx;font-weight:900;margin:24rpx 0}.meta{color:$muted;font-size:22rpx}</style>
